def cancel_duplicate_active_requests(apps, schema_editor):
    """Keep each tenant's oldest open request per home; cancel later duplicates and return their credits."""
    ViewingRequest = apps.get_model("viewings", "ViewingRequest")
    ViewingCreditUse = apps.get_model("payments", "ViewingCreditUse")
    ViewingCreditPurchase = apps.get_model("payments", "ViewingCreditPurchase")
    seen = set()
    for item in ViewingRequest.objects.filter(status__in=("pending_landlord", "approved")).order_by("created_at", "id"):
        key = (item.tenant_id, item.unit_id)
